import pytest from boss.dist import UbuntuVersion from boss.engine import Args from boss.mods.first import First
@pytest.fixture def dummy_args(): return Args( bash=True, servername="testserver", modules=(), dry_run=True, required=False, dependencies=False, generate_script=False, dist_version=None, new_user_and_pass=("user", "pass"), sql_file=None, db_name=None, db_root_pass="rootpass", new_db_user_and_pass=("dbuser", "dbpass"), new_system_user_and_pass=("sysuser", "syspass"), site_name_and_root=[], craft_credentials=("user", "email", "pass"), host_ip=None, netdata_user_pass=("user", "pass"), wanted=[], )
def test_first_ubuntu_14(dummy_args): first = First(args=dummy_args, ubuntu_version=UbuntuVersion.V14_04, dry_run=True) assert "tree" in first.apt_pkgs assert "elinks" in first.apt_pkgs
def test_first_ubuntu_18(dummy_args): first = First(args=dummy_args, ubuntu_version=UbuntuVersion.V18_04, dry_run=True) # Add assertions for expected packages for 18.04 assert isinstance(first.apt_pkgs, list)
def test_first_title(dummy_args): first = First(args=dummy_args, ubuntu_version=UbuntuVersion.V20_04, dry_run=True) assert first.title == "First"
